<svelte:options css="injected" />
<script lang="ts">
 import Theme from '../../shared/Theme.svelte';import type {UiOption} from '../../types';
 let {options,value,onchange,label='页签'}:{options:UiOption[];value:string;onchange?:(value:string)=>void;label?:string}=$props();
 function keys(event:KeyboardEvent){const items=options.filter(o=>!o.disabled);let index=items.findIndex(o=>o.value===value);if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();index=event.key==='Home'?0:event.key==='End'?items.length-1:(index+(event.key==='ArrowRight'?1:-1)+items.length)%items.length; if(items[index]){onchange?.(items[index].value);(event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button:not(:disabled)')[index]?.focus();}}
</script>
<Theme><div class="mc-ui-tabs"><div class="mc-ui-tabs__header is-top"><div class="mc-ui-tabs__nav-wrap is-top"><div class="mc-ui-tabs__nav-scroll"><div class="mc-ui-tabs__nav is-top" role="tablist" tabindex="-1" aria-label={label} onkeydown={keys}>{#each options as option(option.value)}<button class="mc-ui-tabs__item is-top" class:is-active={value===option.value} role="tab" aria-selected={value===option.value} tabindex={value===option.value?0:-1} class:is-disabled={option.disabled} disabled={option.disabled} onclick={()=>onchange?.(option.value)}><span class="mc-ui-tabs__item__title">{option.label}</span></button>{/each}</div></div></div></div></div></Theme>
<style>button{border:0;background:none;font:inherit}button:focus-visible{outline:2px solid var(--tv-Tabs-active-text-color,#191919)!important;outline-offset:-2px}button.is-active{box-shadow:inset 0 -2px var(--tv-Tabs-active-text-color,#191919)}</style>
